shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java
+++ b/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java
@@ -718,6 +718,39 @@
     }

     @Test
+    public void disposeBeforeInnerOnSubscribe() throws Throwable {
+        TestHelper.withErrorTracking(errors -> {
+            for (boolean delayErrors : new boolean[] { false, true }) {
+                PublishSubject<Integer> ps1 = PublishSubject.create();
+                PublishSubject<Integer> ps2 = PublishSubject.create();
+                TestObserver<Integer> to = new TestObserver<>();
+
+                Function<Integer, Observable<Integer>> mapper = v -> Observable.defer(() -> {
+                    to.dispose();
+                    return ps2.scan(0, (a, b) -> a + b).map(Functions.identity());
+                });
+
+                Observable<Integer> result = delayErrors
+                        ? ps1.switchMapDelayError(mapper)
+                        : ps1.switchMap(mapper);
+
+                result.subscribe(to);
+
+                ps1.onNext(1);
+
+                to.assertEmpty();
+                assertTrue(to.isDisposed());
+                assertFalse(ps1.hasObservers());
+                assertFalse(ps2.hasObservers());
+            }
+
+            assertTrue(errors.toString(), errors.isEmpty());
+        });
+    }
+
+    @Test
     public void nextSourceErrorRace() {
         for (int i = 0; i < TestHelper.RACE_DEFAULT_LOOPS; i++) {
             List<Throwable> errors = TestHelper.trackPluginErrors();
PATCH
./gradlew --offline test --tests io.reactivex.rxjava3.internal.operators.observable.ObservableSwitchTest.disposeBeforeInnerOnSubscribe

